-------------------------------------------------------------------------------
-- mt_moon.lua: test harness for the generated Mt. Moon floors
-------------------------------------------------------------------------------
--
-- Mt. Moon's floors are generated by src/mt_moon_gen.c every time the player
-- walks in. Each visit gets a 16-bit seed, stored in the game variable
-- VAR_MT_MOON_MAP_SEED, and the whole cave is a function of that seed. This
-- library lets tests:
--
--   * enter a floor with a chosen value of the game's random number state
--     (gRngValue), so a run can be reproduced exactly;
--   * read back everything the generator produced: the seed, the map grid,
--     the warps, the background events (signs and hidden items) and the
--     object templates (where trainers and item balls start);
--   * search the map with a breadth-first search (BFS);
--   * save the game through the START menu and load it again with CONTINUE.
--
-- Property checks (test/tests/mt_moon_checks/*.lua) and scenario tests
-- (test/tests/test_mt_moon_*.lua) are built on top of it.
--
-- GBA BACKGROUND FOR READERS NEW TO IT:
--
--   * A map is a grid of "metatiles", 16x16-pixel blocks. In RAM each map cell
--     is one 16-bit number: bits 0-9 are the metatile id (which picture to
--     draw), bits 10-11 the collision value (0 = walkable) and bits 12-15 the
--     elevation. For example 0x3281 is metatile 0x281 (cave floor),
--     collision 0, elevation 3.
--   * The engine keeps the loaded map in a bigger buffer, the "VMap", with a
--     7-tile margin on every side (MAP_OFFSET) so the camera can scroll past
--     the edge. Map cell (x, y) lives at VMap cell (x + 7, y + 7). Object
--     coordinates in gObjectEvents use the same +7 convention.
--   * All addresses are looked up by name in pokefirered.elf (see
--     symbols.lua), so a rebuild that moves variables doesn't break the tests.
--     Struct field offsets can't be looked up that way; the ones used here
--     are listed below with how they were derived.
--
-- Everything that waits for frames must be called from inside fw.run().
-------------------------------------------------------------------------------

local script_dir = debug.getinfo(1, "S").source:match("@?(.*/)") or ""
local project_dir = script_dir .. "../../"

local fw  = dofile(project_dir .. "test/lib/framework.lua")
local sym = dofile(project_dir .. "test/lib/symbols.lua")

local mm = {}

-------------------------------------------------------------------------------
-- Constants
-------------------------------------------------------------------------------

-- Map ids are (group, number) pairs; see include/constants/map_groups.h.
-- Mt. Moon's floors are in group 1 (dungeons); Route 4 is group 3.
mm.DUNGEON_GROUP = 1
mm.ROUTE4 = { group = 3, num = 22 }

-- An untouched vanilla cave, for comparing load times (P9): Rock Tunnel 1F
-- (map 1.81) is the same size as the Mt. Moon floors, 48 x 40 tiles.
mm.VANILLA_CAVE = { name = "Rock Tunnel 1F", group = 1, num = 81, warp = 0 }

-- The generated floors, in the order of the chain they form:
--
--   Route 4 west door <-> 1F <-> B1F <-> B2F <-> Route 4 east door
--
-- Each floor has exactly two active warps (every other vanilla warp of the
-- floor is parked at (0,0), a solid wall tile nobody can stand on):
--
--   entrance  the warp toward Route 4 WEST. A west-to-east walk arrives here.
--   exit      the warp toward Route 4 EAST. A west-to-east walk leaves here.
--
-- `warp` is the warp's index in the floor's warp table (map.json order),
-- `to` is where it leads (map group, map number, warp index there), and
-- `kind` is what the warp tile looks like, following vanilla Mt. Moon:
--
--   "door"  1F's doorway at the south edge of the map: walkable metatile
--           0x287 with the doorframe (0x2c8 0x2c9 0x2ca) below it. Standing
--           on it and pressing DOWN leaves the cave.
--   "down"  a down-ladder: a hole (0x285 or 0x2af) in open floor, i.e. all
--           8 tiles around it are walkable. Stepping onto it warps.
--   "up"    an up-ladder: the ladder's foot (0x296, walkable) at the foot of
--           a north wall, with the ladder's top (0x28f, solid) set into the
--           wall above it, as on vanilla B1F. Stepping onto the foot warps.
--   "up_in_floor"
--           an up-ladder standing in open floor, as all four of vanilla
--           B2F's are: the foot 0x296 (walkable) with the ladder's top
--           0x28e (solid) right above it, and walkable floor all around
--           both. Stepping onto the foot warps.
--
-- `arrival_warp` and `exit_warp` are the entrance and exit warp indexes,
-- kept under the names older tests use: mm.enter_floor() arrives through
-- `arrival_warp`.
local ROUTE4_GROUP, ROUTE4_NUM = mm.ROUTE4.group, mm.ROUTE4.num
mm.FLOORS = {
    {
        name = "1F", group = 1, num = 1,
        entrance = { warp = 3, kind = "door", to = { group = ROUTE4_GROUP, num = ROUTE4_NUM, warp = 0 } },
        exit     = { warp = 0, kind = "down", to = { group = 1, num = 2, warp = 0 } },
    },
    {
        name = "B1F", group = 1, num = 2,
        entrance = { warp = 0, kind = "up",   to = { group = 1, num = 1, warp = 0 } },
        exit     = { warp = 3, kind = "down", to = { group = 1, num = 3, warp = 0 } },
    },
    {
        name = "B2F", group = 1, num = 3,
        entrance = { warp = 0, kind = "up_in_floor", to = { group = 1, num = 2, warp = 3 } },
        exit     = { warp = 1, kind = "up_in_floor", to = { group = ROUTE4_GROUP, num = ROUTE4_NUM, warp = 1 } },
    },
}
for _, floor in ipairs(mm.FLOORS) do
    floor.arrival_warp = floor.entrance.warp
    floor.exit_warp = floor.exit.warp
end

-- Route 4's two cave doors (warp index -> tile), from data/maps/Route4.
mm.ROUTE4_WEST_DOOR = { warp = 0, x = 19, y = 5 }  -- leads into 1F
mm.ROUTE4_EAST_DOOR = { warp = 1, x = 32, y = 5 }  -- leads into B2F

-- The minimum distance between a floor's two ladders, counted as steps east
-- or west plus steps north or south (Manhattan distance).
mm.MIN_LADDER_DISTANCE = 24

function mm.floor_by_name(name)
    for _, floor in ipairs(mm.FLOORS) do
        if floor.name == name then return floor end
    end
    return nil
end

mm.MAP_OFFSET = 7

-- Field offsets inside struct SaveBlock1 (include/global.h). This fork's
-- SaveBlock1 differs from vanilla, so these were measured by compiling
--     offsetof(struct SaveBlock1, vars)   (and so on)
-- with agbcc and reading the result from the generated assembly. They only
-- change if someone edits struct SaveBlock1.
local SB1_POS              = 0x0000  -- struct Coords16 pos: s16 x, s16 y
local SB1_LOCATION         = 0x0004  -- struct WarpData location
local SB1_OBJECT_EVENTS    = 0x06c8  -- struct ObjectEvent objectEvents[16]
local SB1_OBJECT_TEMPLATES = 0x0908  -- struct ObjectEventTemplate [64]
local SB1_FLAGS            = 0x0F08  -- u8 flags[], one bit per flag, flag 0 first
local SB1_VARS             = 0x1028  -- u16 vars[VARS_COUNT], var 0x4000 first

-- Game variables 0x4000 and up are stored in SaveBlock1.vars, 2 bytes each.
mm.VAR_MT_MOON_MAP_SEED = 0x4029
local VARS_START = 0x4000

-- struct ObjectEvent (include/global.fieldmap.h), 0x24 bytes each.
local OE_SIZE       = 0x24
local OE_FLAGS      = 0x00  -- bit 0 = active, bit 16 = isPlayer
local OE_LOCAL_ID   = 0x08
local OE_MAP_NUM    = 0x09
local OE_MAP_GROUP  = 0x0A
local OE_INITIAL    = 0x0C  -- initialCoords  (s16 x, s16 y)
local OE_CURRENT    = 0x10  -- currentCoords
local OE_PREVIOUS   = 0x14  -- previousCoords
local OE_FACING     = 0x18  -- facingDirection in bits 0-3: DIR_SOUTH 1,
                            -- DIR_NORTH 2, DIR_WEST 3, DIR_EAST 4

-- struct ObjectEventTemplate (include/global.fieldmap.h), 0x18 bytes each:
--   +0x00 u8 localId     +0x01 u8 graphicsId   +0x02 u8 kind
--   +0x04 s16 x          +0x06 s16 y
--   +0x08 u8 elevation   +0x09 u8 movementType
--   +0x0A u16 with movementRangeX in bits 0-3 and movementRangeY in bits 4-7
--   +0x0C u16 trainerType (0 = TRAINER_TYPE_NONE: not a trainer)
--   +0x10 script pointer +0x14 u16 flagId (object hidden while the flag is set)
-- read_template() below reads these offsets in this order.
local TEMPLATE_SIZE = 0x18

-- struct MapHeader: mapLayout at +0, events at +4, mapLayoutId (u16) at +0x12.
-- struct MapLayout: s32 width at +0, s32 height at +4.
-- struct MapEvents: four u8 counts (objects, warps, coord events, bg events)
-- followed by four pointers to the matching arrays.
-- struct WarpEvent, 8 bytes: s16 x, s16 y, u8 elevation, u8 warpId (the
-- destination map's warp), u8 mapNum, u8 mapGroup (the destination map).
-- struct CoordEvent, 16 bytes: u16 x, u16 y, u8 elevation, 1 byte of
-- padding, u16 trigger (the game variable it watches), u16 index (the value
-- that variable must hold for the script to run), 2 bytes of padding, then
-- the script pointer. A coordinate event is an invisible tile that starts
-- its script when the player steps onto it, such as Miguel's battle trigger.
-- struct BgEvent, 12 bytes: u16 x, u16 y, u8 elevation, u8 kind, 2 bytes of
-- padding, then a u32 (script pointer, or packed hidden-item data).
local WARP_SIZE = 8
local COORD_EVENT_SIZE = 16
local BG_EVENT_SIZE = 12

-- The tile collision value lives in bits 10-11 of a map cell.
function mm.collision(cell)
    return (cell >> 10) & 3
end

function mm.metatile(cell)
    return cell & 0x3ff
end

function mm.passable(cell)
    return cell ~= nil and mm.collision(cell) == 0
end

-------------------------------------------------------------------------------
-- Small memory helpers
-------------------------------------------------------------------------------

local function s16(v)
    if v >= 0x8000 then return v - 0x10000 end
    return v
end

local function key(x, y)
    return y * 1000 + x
end
mm.key = key

function mm.sb1()
    return emu:read32(sym.addr("gSaveBlock1Ptr"))
end

local function callback2()
    return emu:read32(sym.addr("gMain") + 4)
end

function mm.in_overworld()
    return sym.is_func(callback2(), "CB2_Overworld")
end

-- The current visit's cave seed, as stored in the save.
function mm.seed()
    return emu:read16(mm.sb1() + SB1_VARS + (mm.VAR_MT_MOON_MAP_SEED - VARS_START) * 2)
end

-- Overwrite the stored seed (e.g. 0, to imitate a save made before cave
-- seeds existed). Takes effect at the next Continue.
function mm.set_seed(value)
    emu:write16(mm.sb1() + SB1_VARS + (mm.VAR_MT_MOON_MAP_SEED - VARS_START) * 2, value & 0xFFFF)
end

-- Any game variable 0x4000 and up (include/constants/vars.h).
function mm.get_var(var)
    return emu:read16(mm.sb1() + SB1_VARS + (var - VARS_START) * 2)
end

function mm.set_var(var, value)
    emu:write16(mm.sb1() + SB1_VARS + (var - VARS_START) * 2, value & 0xFFFF)
end

-- Any flag (include/constants/flags.h): flag n is bit n % 8 of byte n / 8.
function mm.get_flag(flag)
    return (emu:read8(mm.sb1() + SB1_FLAGS + (flag >> 3)) >> (flag & 7)) & 1 == 1
end

function mm.set_flag(flag)
    local a = mm.sb1() + SB1_FLAGS + (flag >> 3)
    emu:write8(a, emu:read8(a) | (1 << (flag & 7)))
end

function mm.clear_flag(flag)
    local a = mm.sb1() + SB1_FLAGS + (flag >> 3)
    emu:write8(a, emu:read8(a) & ~(1 << (flag & 7)) & 0xFF)
end

-- The OPTION menu's text speed, SaveBlock2.optionsTextSpeed (include/
-- global.h): bits 0-2 of the u16 at offset 0x14 of SaveBlock2.
local SB2_OPTIONS = 0x14

-- Set the text speed option to FAST, as a player in a hurry would (a new
-- game starts at MID). Scenario tests that time a scripted scene with
-- several messages use it, so their frame limits measure the scene, not
-- the text printer.
function mm.set_text_speed_fast()
    local fast = mm.read_defines("include/constants/global.h").OPTIONS_TEXT_SPEED_FAST
    local a = emu:read32(sym.addr("gSaveBlock2Ptr")) + SB2_OPTIONS
    emu:write16(a, (emu:read16(a) & ~7) | fast)
end

-- Reads `#define NAME value` constants from a header in the repo, so tests
-- use the same numbers as the game instead of copying them.
-- Returns name -> number for every define whose value is a plain number
-- (optionally followed by a // or /* comment).
function mm.read_defines(path)
    local defines = {}
    local f = io.open(project_dir .. path, "r")
    if f == nil then error("can't read " .. path) end
    for line in f:lines() do
        local name, value, rest = line:match("^#define%s+([%w_]+)%s+(0?x?%x+)%s*(.*)$")
        if name and (rest == "" or rest:match("^//") or rest:match("^/%*")) then
            defines[name] = tonumber(value)
        end
    end
    f:close()
    return defines
end

-- Mark every trainer that battles in Mt. Moon as already defeated, so no
-- trainer starts a battle when the player walks into their sight line.
-- The trainers are read from the floors' scripts (every
-- `trainerbattle_* TRAINER_X` line); a trainer's "defeated" flag is
-- TRAINER_FLAGS_START + its id (include/constants/flags.h, opponents.h).
-- Returns the list of trainer names marked.
function mm.mark_mt_moon_trainers_defeated()
    local opponents = mm.read_defines("include/constants/opponents.h")
    -- flags.h defines TRAINER_FLAGS_START as (FLAG_0x4FF + 1).
    local flags_start = mm.read_defines("include/constants/flags.h").FLAG_0x4FF + 1
    local names = {}
    for _, map in ipairs({ "MtMoon_1F", "MtMoon_B1F", "MtMoon_B2F" }) do
        local f = io.open(project_dir .. "data/maps/" .. map .. "/scripts.inc", "r")
        if f then
            for line in f:lines() do
                local name = line:match("trainerbattle_[%w_]+%s+(TRAINER_[%w_]+)")
                if name and opponents[name] then
                    mm.set_flag(flags_start + opponents[name])
                    names[#names + 1] = name
                end
            end
            f:close()
        end
    end
    return names
end

-- How many of item `item_id` (include/constants/items.h) the bag holds,
-- over all its pockets. gBagPockets (src/item.c) is an array of
-- NUM_BAG_POCKETS { struct ItemSlot *itemSlots; u8 capacity; } entries,
-- 8 bytes each (the u8 is padded to 4 bytes). Each ItemSlot is
-- { u16 itemId; u16 quantity; }, and the quantity is stored XORed with the
-- low 16 bits of SaveBlock2.encryptionKey (offset 0xF20, include/global.h),
-- a per-save number the game uses so cheat devices can't find item counts
-- by searching memory for them.
local NUM_BAG_POCKETS = 5
local SB2_ENCRYPTION_KEY = 0xF20

function mm.bag_quantity(item_id)
    local pockets = sym.addr("gBagPockets")
    local key = emu:read16(emu:read32(sym.addr("gSaveBlock2Ptr")) + SB2_ENCRYPTION_KEY)
    local total = 0
    for p = 0, NUM_BAG_POCKETS - 1 do
        local slots = emu:read32(pockets + p * 8)
        local capacity = emu:read8(pockets + p * 8 + 4)
        for i = 0, capacity - 1 do
            if emu:read16(slots + i * 4) == item_id then
                total = total + (emu:read16(slots + i * 4 + 2) ~ key)
            end
        end
    end
    return total
end

-- The game's global random number state. Random() advances it with
-- state = state * 1103515245 + 24691 and returns the top 16 bits.
function mm.rng()
    return emu:read32(sym.addr("gRngValue"))
end

function mm.set_rng(value)
    emu:write32(sym.addr("gRngValue"), value & 0xFFFFFFFF)
end

function mm.current_map()
    local sb1 = mm.sb1()
    return emu:read8(sb1 + SB1_LOCATION + 0), emu:read8(sb1 + SB1_LOCATION + 1)
end

function mm.on_floor(floor)
    local group, num = mm.current_map()
    return group == floor.group and num == floor.num
end

-------------------------------------------------------------------------------
-- Reading what the generator produced
-------------------------------------------------------------------------------

-- The map currently loaded, as { w, h, cells, key }. cells[key(x, y)] is the
-- 16-bit map cell at map coordinates (x, y). `key` is the whole grid packed
-- into one string, so two grids can be compared with a single `==`.
function mm.read_grid()
    local header = sym.addr("gMapHeader")
    local layout = emu:read32(header)
    local w = emu:read32(layout + 0)
    local h = emu:read32(layout + 4)
    local vmap = sym.addr("VMap")
    local vmap_w = emu:read32(vmap + 0)
    local vmap_cells = emu:read32(vmap + 8)
    local cells, parts = {}, {}
    for y = 0, h - 1 do
        local row = vmap_cells + ((y + mm.MAP_OFFSET) * vmap_w + mm.MAP_OFFSET) * 2
        for x = 0, w - 1 do
            local v = emu:read16(row + x * 2)
            cells[key(x, y)] = v
            parts[#parts + 1] = string.format("%04x", v)
        end
    end
    return { w = w, h = h, cells = cells, key = table.concat(parts) }
end

-- First (x, y) where two grids differ, or nil if they are identical.
function mm.first_grid_difference(a, b)
    if a.w ~= b.w or a.h ~= b.h then
        return -1, -1, string.format("size %dx%d vs %dx%d", a.w, a.h, b.w, b.h)
    end
    for y = 0, a.h - 1 do
        for x = 0, a.w - 1 do
            local va, vb = a.cells[key(x, y)], b.cells[key(x, y)]
            if va ~= vb then
                return x, y, string.format("0x%04x vs 0x%04x", va, vb)
            end
        end
    end
    return nil
end

local function map_events()
    return emu:read32(sym.addr("gMapHeader") + 4)
end

-- The current map's warps, 1-based: warps[1] is warp id 0.
function mm.read_warps()
    local events = map_events()
    local count = emu:read8(events + 1)
    local base = emu:read32(events + 8)
    local warps = {}
    for i = 0, count - 1 do
        local a = base + i * WARP_SIZE
        warps[#warps + 1] = {
            id = i,
            x = s16(emu:read16(a + 0)),
            y = s16(emu:read16(a + 2)),
            elevation = emu:read8(a + 4),
            dest_warp = emu:read8(a + 5),
            dest_num = emu:read8(a + 6),
            dest_group = emu:read8(a + 7),
        }
    end
    return warps
end

-- `count` background events (signs and hidden items) starting at `base`.
local function read_bg_event_array(base, count)
    local bgs = {}
    for i = 0, count - 1 do
        local a = base + i * BG_EVENT_SIZE
        bgs[#bgs + 1] = {
            x = emu:read16(a + 0),
            y = emu:read16(a + 2),
            elevation = emu:read8(a + 4),
            kind = emu:read8(a + 5),
            data = emu:read32(a + 8),
        }
    end
    return bgs
end

-- The current map's background events (signs and hidden items).
function mm.read_bg_events()
    local events = map_events()
    return read_bg_event_array(emu:read32(events + 16), emu:read8(events + 3))
end

-- `count` coordinate events (layout above) starting at `base`.
local function read_coord_event_array(base, count)
    local coords = {}
    for i = 0, count - 1 do
        local a = base + i * COORD_EVENT_SIZE
        coords[#coords + 1] = {
            x = emu:read16(a + 0),
            y = emu:read16(a + 2),
            elevation = emu:read8(a + 4),
            var = emu:read16(a + 6),
            value = emu:read16(a + 8),
            script = emu:read32(a + 12),
        }
    end
    return coords
end

-- The current map's coordinate events (trigger tiles).
function mm.read_coord_events()
    local events = map_events()
    return read_coord_event_array(emu:read32(events + 12), emu:read8(events + 2))
end

-- One struct ObjectEventTemplate at address `a` (layout above).
local function read_template(a)
    local ranges = emu:read16(a + 10)
    return {
        local_id = emu:read8(a + 0),
        graphics_id = emu:read8(a + 1),
        kind = emu:read8(a + 2),
        x = s16(emu:read16(a + 4)),
        y = s16(emu:read16(a + 6)),
        elevation = emu:read8(a + 8),
        movement_type = emu:read8(a + 9),
        range_x = ranges & 0xF,
        range_y = (ranges >> 4) & 0xF,
        trainer_type = emu:read16(a + 0x0C),
        flag = emu:read16(a + 0x14),
    }
end

-- The object templates for the current map: where each trainer, NPC and item
-- ball starts. They live in the save block, so they survive save/Continue.
function mm.read_templates()
    local count = emu:read8(map_events() + 0)
    local base = mm.sb1() + SB1_OBJECT_TEMPLATES
    local templates = {}
    for i = 0, count - 1 do
        templates[#templates + 1] = read_template(base + i * TEMPLATE_SIZE)
    end
    return templates
end

-- A map's events exactly as the ROM stores them: the vanilla map.json data,
-- before the generator rewrites anything. Every map's header is reached
-- through gMapGroups[group][num] (an array of header pointers per map
-- group); the header's `events` (+4) points at struct MapEvents (layout
-- above). Returns { objects = {...}, coord_events = {...},
-- bg_events = {...} } in map.json order.
function mm.rom_events(map)
    local group_list = emu:read32(sym.addr("gMapGroups") + map.group * 4)
    local header = emu:read32(group_list + map.num * 4)
    local events = emu:read32(header + 4)
    local objects = {}
    local object_base = emu:read32(events + 4)
    for i = 0, emu:read8(events + 0) - 1 do
        objects[#objects + 1] = read_template(object_base + i * TEMPLATE_SIZE)
    end
    return {
        objects = objects,
        coord_events = read_coord_event_array(emu:read32(events + 12), emu:read8(events + 2)),
        bg_events = read_bg_event_array(emu:read32(events + 16), emu:read8(events + 3)),
    }
end

-------------------------------------------------------------------------------
-- Where an object can be
-------------------------------------------------------------------------------
--
-- Most Mt. Moon objects stand still. A few move around inside a box set by
-- the template's movement range (the game refuses any step that would leave
-- it: COLLISION_OUTSIDE_RANGE in src/event_object_movement.c):
--
--   wanderers (MOVEMENT_TYPE_WANDER_*, walkers, copiers) can be anywhere in
--       [x - range_x, x + range_x] x [y - range_y, y + range_y];
--   MOVEMENT_TYPE_WALK_SEQUENCE_LEFT_DOWN_RIGHT_UP (1F's Lass Miriam) walks
--       west to x - range_x, south to y + range_y, east back to x and north
--       back to y (MovementType_WalkSequenceLeftDownRightUp_Step1), so she
--       stays in [x - range_x, x] x [y, y + range_y].
--
-- Reachability checks treat that whole box as solid: the object could be
-- standing on any tile of it.

mm.MOVEMENT = mm.read_defines("include/constants/event_object_movement.h")

-- Background event kinds (BG_EVENT_HIDDEN_ITEM, BG_EVENT_PLAYER_FACING_*).
mm.BG_EVENT = mm.read_defines("include/constants/event_bg.h")

-- The one-tile prefabs the design (#22, section 3) puts under hidden items
-- and signs, as metatile ids: the lone boulder every vanilla Mt. Moon hidden
-- item sits on, and the signpost. Kept here as the design states them,
-- not read from the generator, so the checks stay an independent source.
mm.BOULDER = 0x282
mm.SIGNPOST = 0x2cd

local MOVING_TYPES = {}
for name, value in pairs(mm.MOVEMENT) do
    if name:match("^MOVEMENT_TYPE_WANDER_") or name:match("^MOVEMENT_TYPE_WALK_UP_AND_DOWN")
        or name:match("^MOVEMENT_TYPE_WALK_DOWN_AND_UP") or name:match("^MOVEMENT_TYPE_WALK_LEFT_AND_RIGHT")
        or name:match("^MOVEMENT_TYPE_WALK_RIGHT_AND_LEFT") or name:match("^MOVEMENT_TYPE_WALK_SEQUENCE_")
        or name:match("^MOVEMENT_TYPE_COPY_PLAYER") then
        MOVING_TYPES[value] = true
    end
end

-- The box of tiles object template `t` can stand on: x1, y1, x2, y2
-- (inclusive). A standing object's box is its own tile.
function mm.roaming_box(t)
    local rx, ry = t.range_x, t.range_y
    if t.movement_type == mm.MOVEMENT.MOVEMENT_TYPE_WALK_SEQUENCE_LEFT_DOWN_RIGHT_UP then
        return t.x - rx, t.y, t.x, t.y + ry
    elseif MOVING_TYPES[t.movement_type] then
        return t.x - rx, t.y - ry, t.x + rx, t.y + ry
    end
    return t.x, t.y, t.x, t.y
end

-- Every tile any object of the snapshot could stand on, as a set of
-- key(x, y): each object's tile, and each mover's whole box.
function mm.object_tiles(snap)
    local set = {}
    for _, t in ipairs(snap.templates) do
        local x1, y1, x2, y2 = mm.roaming_box(t)
        for y = y1, y2 do
            for x = x1, x2 do set[key(x, y)] = true end
        end
    end
    return set
end

-- The tiles a player can stand on to face the box x1..x2, y1..y2: the
-- tiles just outside it to the north, south, west and east (not the
-- diagonal corners: you can't face anything diagonally).
function mm.facing_tiles(x1, y1, x2, y2)
    local tiles = {}
    for x = x1, x2 do
        tiles[#tiles + 1] = { x, y1 - 1 }
        tiles[#tiles + 1] = { x, y2 + 1 }
    end
    for y = y1, y2 do
        tiles[#tiles + 1] = { x1 - 1, y }
        tiles[#tiles + 1] = { x2 + 1, y }
    end
    return tiles
end

-- Address of live object event `i` (0-15). `saved` = true reads the copy in
-- the save block instead of the working copy in gObjectEvents.
local function object_addr(i, saved)
    if saved then
        return mm.sb1() + SB1_OBJECT_EVENTS + i * OE_SIZE
    end
    return sym.addr("gObjectEvents") + i * OE_SIZE
end

-- Every active object event on screen right now, in map coordinates.
-- `saved` = true lists the copy in the save block instead: the objects as
-- they were at the moment of the last save.
function mm.live_objects(saved)
    local objects = {}
    for i = 0, 15 do
        local a = object_addr(i, saved)
        local flags = emu:read32(a + OE_FLAGS)
        if (flags & 1) ~= 0 then
            objects[#objects + 1] = {
                index = i,
                is_player = (flags & 0x10000) ~= 0,
                local_id = emu:read8(a + OE_LOCAL_ID),
                map_num = emu:read8(a + OE_MAP_NUM),
                map_group = emu:read8(a + OE_MAP_GROUP),
                x = s16(emu:read16(a + OE_CURRENT)) - mm.MAP_OFFSET,
                y = s16(emu:read16(a + OE_CURRENT + 2)) - mm.MAP_OFFSET,
                -- Where it is walking from. During a step an object already
                -- counts as standing on its destination (x, y) and still
                -- blocks the tile it left.
                prev_x = s16(emu:read16(a + OE_PREVIOUS)) - mm.MAP_OFFSET,
                prev_y = s16(emu:read16(a + OE_PREVIOUS + 2)) - mm.MAP_OFFSET,
                facing = emu:read8(a + OE_FACING) & 0xF,
            }
        end
    end
    return objects
end

-- True for a roaming Pokemon (src/roaming_pokemon.c), as listed by
-- mm.live_objects: local ids 200-205. Not "200 and up": the walking Pokemon
-- (the follower) is 254 and the player 255.
function mm.is_roamer(o)
    return not o.is_player and o.local_id >= 200 and o.local_id <= 205
end

local function player_object_index()
    for _, obj in ipairs(mm.live_objects()) do
        if obj.is_player then return obj.index end
    end
    return nil
end

function mm.player_tile()
    for _, obj in ipairs(mm.live_objects()) do
        if obj.is_player then return obj.x, obj.y end
    end
    return nil
end

-- Teleport the player to map tile (x, y) without any game logic: rewrites
-- the player's object coordinates and SaveBlock1.pos, which are exactly what
-- a save stores. The sprite on screen doesn't move until the map is next
-- loaded (for example by Continue). Used to put the player somewhere a real
-- walk can't reach, such as inside a wall.
function mm.poke_player(x, y)
    local i = player_object_index()
    assert(i ~= nil, "no player object to move")
    local vx, vy = x + mm.MAP_OFFSET, y + mm.MAP_OFFSET
    for _, saved in ipairs({ false, true }) do
        local a = object_addr(i, saved)
        for _, field in ipairs({ OE_INITIAL, OE_CURRENT, OE_PREVIOUS }) do
            emu:write16(a + field, vx & 0xFFFF)
            emu:write16(a + field + 2, vy & 0xFFFF)
        end
    end
    local sb1 = mm.sb1()
    emu:write16(sb1 + SB1_POS + 0, x & 0xFFFF)
    emu:write16(sb1 + SB1_POS + 2, y & 0xFFFF)
end

-- Move live object `index` (as listed by mm.live_objects) to map tile
-- (x, y) by rewriting its current and previous coordinates. No game logic
-- runs and the sprite isn't moved; used to put an object out of the way.
function mm.poke_object(index, x, y)
    local a = object_addr(index, false)
    local vx, vy = (x + mm.MAP_OFFSET) & 0xFFFF, (y + mm.MAP_OFFSET) & 0xFFFF
    for _, field in ipairs({ OE_CURRENT, OE_PREVIOUS }) do
        emu:write16(a + field, vx)
        emu:write16(a + field + 2, vy)
    end
end

-- Everything the generator decides for the loaded floor, plus where the
-- player and the live objects are. Checks compare and inspect these.
-- `saved_objects` = true takes the player and objects from the save block's
-- copy (their positions at the last save) instead of the live ones.
function mm.snapshot(saved_objects)
    local group, num = mm.current_map()
    local live = mm.live_objects(saved_objects)
    local px, py = nil, nil
    for _, obj in ipairs(live) do
        if obj.is_player then px, py = obj.x, obj.y end
    end
    return {
        group = group,
        num = num,
        seed = mm.seed(),
        grid = mm.read_grid(),
        warps = mm.read_warps(),
        coord_events = mm.read_coord_events(),
        bg_events = mm.read_bg_events(),
        templates = mm.read_templates(),
        live = live,
        player_x = px,
        player_y = py,
        -- SaveBlock1.pos: the map position the engine draws the view around
        -- and saves. It should always equal the player's tile.
        pos_x = s16(emu:read16(mm.sb1() + SB1_POS + 0)),
        pos_y = s16(emu:read16(mm.sb1() + SB1_POS + 2)),
    }
end

-- "x,y x,y ..." for every template, for comparing placements in one go.
function mm.template_positions(snap)
    local parts = {}
    for _, t in ipairs(snap.templates) do
        parts[#parts + 1] = string.format("%d:%d,%d", t.local_id, t.x, t.y)
    end
    return table.concat(parts, " ")
end

-- "id@x,y ..." for every non-player live object, sorted by local id.
function mm.live_positions(snap)
    local parts = {}
    for _, obj in ipairs(snap.live) do
        if not obj.is_player then
            parts[#parts + 1] = string.format("%d@%d,%d", obj.local_id, obj.x, obj.y)
        end
    end
    table.sort(parts)
    return table.concat(parts, " ")
end

-------------------------------------------------------------------------------
-- Breadth-first search
-------------------------------------------------------------------------------

-- Distance in steps from (sx, sy) to every tile reachable by walking N/S/E/W
-- over walkable tiles. `blocked(x, y)` (optional) marks extra solid tiles,
-- such as tiles under objects. `stop(x, y)` (optional) marks tiles that can
-- be reached but not walked through, such as a warp: stepping onto a ladder
-- leaves the map. Returns dist[key(x, y)] = steps.
function mm.bfs(grid, sx, sy, blocked, stop)
    local dist = { [key(sx, sy)] = 0 }
    local queue, head = { { sx, sy } }, 1
    local steps = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }
    while head <= #queue do
        local cx, cy = queue[head][1], queue[head][2]
        head = head + 1
        local d = dist[key(cx, cy)]
        for _, s in ipairs(steps) do
            local nx, ny = cx + s[1], cy + s[2]
            local k = key(nx, ny)
            if dist[k] == nil and nx >= 0 and ny >= 0 and nx < grid.w and ny < grid.h
                and mm.passable(grid.cells[k])
                and not (blocked and blocked(nx, ny)) then
                dist[k] = d + 1
                if not (stop and stop(nx, ny)) then
                    queue[#queue + 1] = { nx, ny }
                end
            end
        end
    end
    return dist
end

-- The floor's two active warps from a snapshot, as { entrance = warp,
-- exit = warp } (see FLOORS).
function mm.ladder_warps(floor, snap)
    return {
        entrance = snap.warps[floor.entrance.warp + 1],
        exit = snap.warps[floor.exit.warp + 1],
    }
end

-- The set of key(x, y) of the floor's two active warps (mm.ladder_warps).
function mm.warp_tile_set(ladders)
    return {
        [key(ladders.entrance.x, ladders.entrance.y)] = true,
        [key(ladders.exit.x, ladders.exit.y)] = true,
    }
end

-- Reachability as the player has it after arriving through warp `from`
-- (one of mm.ladder_warps): the BFS distances from the arrival tile, where
-- every tile an object could stand on is solid (mm.object_tiles) and the
-- floor's other warp `to` can be reached but not walked through. Returns
-- dist (see mm.bfs) and the object tile set.
function mm.reach_from_warp(snap, from, to)
    local objects = mm.object_tiles(snap)
    local dist = mm.bfs(snap.grid, from.x, from.y,
        function(x, y) return objects[key(x, y)] end,
        function(x, y) return x == to.x and y == to.y end)
    return dist, objects
end

-- The player arrives on a floor through either warp, depending on which way
-- they are going. Calls fn(label, dist, objects, from, to) once per arrival
-- warp, with mm.reach_from_warp's results, and stops at the first call
-- that returns false (plus a reason), returning that; otherwise true.
function mm.check_each_arrival(floor, snap, fn)
    local ladders = mm.ladder_warps(floor, snap)
    for _, arrival in ipairs({ "entrance", "exit" }) do
        local from = ladders[arrival]
        local to = ladders[arrival == "entrance" and "exit" or "entrance"]
        local dist, objects = mm.reach_from_warp(snap, from, to)
        local label = string.format("arriving at the %s (%d,%d)", arrival, from.x, from.y)
        local ok, why = fn(label, dist, objects, from, to)
        if not ok then return false, why end
    end
    return true
end

-- The warp the player arrives through on `floor`, from a snapshot.
function mm.arrival_warp(floor, snap)
    return snap.warps[floor.arrival_warp + 1]
end

-- Tiles reachable on foot from the floor's arrival warp.
function mm.reachable_from_arrival(floor, snap)
    local warp = mm.arrival_warp(floor, snap)
    return mm.bfs(snap.grid, warp.x, warp.y)
end

-------------------------------------------------------------------------------
-- Entering a floor with a chosen random state
-------------------------------------------------------------------------------

-- Fresh entry into `floor` through its arrival warp, the same way the warp at
-- the end of a door or ladder does it, with the game's random state set to
-- `rng` first. The seed the generator rolls depends only on `rng`, so calling
-- this twice with the same `rng` must give the same seed. Returns a snapshot
-- once the map has finished loading, and the number of frames that took.
--
-- How the warp works: write the destination into sWarpDestination and
-- SaveBlock1.location (what ApplyCurrentWarp() does), then point
-- gMain.callback2 at CB2_LoadMap. That is the main-loop function that loads a
-- map; when it finishes it switches callback2 to CB2_Overworld. A real warp
-- (door, ladder) does exactly this once its fade to black has finished.
--
-- `warp_id` picks the destination warp the player arrives on; -1 means "no
-- warp", and the player is put on tile (x, y) instead.
--
-- The warp is only handed over while the game is idle. Each frame, the
-- game's main loop does that frame's work and then spins in WaitForVBlank
-- until the next frame starts; the test runs once per frame, at that
-- frame boundary. Usually the loop is already spinning by then, but the
-- first frames on a freshly loaded map can take longer than a frame. If
-- the test wrote the warp mid-frame, the game would start loading one frame
-- earlier than usual, one fewer per-frame Random() call would happen
-- before the seed roll, and the same gRngValue would roll a different seed.
--
-- Even when the loop is spinning at the boundary, it can miss the next
-- frame: a frame whose work ran past the start of the next frame enters
-- WaitForVBlank late, and WaitForVBlank then sleeps through one more
-- frame. The test can't tell the two apart beforehand, so the random state
-- is re-written at every frame boundary until the game has really picked
-- the warp up (callback2 is no longer CB2_LoadMap; see the frame callback
-- below). Then the Random() calls between the test's write and the seed
-- roll are the same whatever map is being left. Without this, a few
-- gRngValues alternated between two caves for ever on one floor: leaving
-- cave A rolled B, leaving B rolled A, one Random() call apart.
local pending_rng = nil

callbacks:add("frame", function()
    if pending_rng == nil then return end
    if sym.is_func(emu:read32(sym.addr("gMain") + 4), "CB2_LoadMap") then
        mm.set_rng(pending_rng)
    else
        pending_rng = nil
    end
end)

local function wait_until_idle()
    for _ = 1, 60 do
        if sym.contains(emu:readRegister("pc"), "WaitForVBlank") then return end
        fw.yield()
    end
end

-- The tile of warp `warp_id` in the ROM's warp table of `map`. The ROM keeps
-- every map's header in gMapGroups[group][num] (an array of pointers per
-- map group); the header's `events` (+4) points at struct MapEvents, whose
-- `warps` pointer is at +8.
local function rom_warp_tile(map, warp_id)
    local group_list = emu:read32(sym.addr("gMapGroups") + map.group * 4)
    local header = emu:read32(group_list + map.num * 4)
    local events = emu:read32(header + 4)
    local warp = emu:read32(events + 8) + warp_id * WARP_SIZE
    return s16(emu:read16(warp + 0)), s16(emu:read16(warp + 2))
end

local function start_warp(map, warp_id, rng, x, y)
    local dest = sym.addr("sWarpDestination")
    local sb1 = mm.sb1()
    wait_until_idle()
    -- A real warp puts the player on the destination tile before the map
    -- loads (WarpIntoMap -> SetPlayerCoordsFromWarp in src/overworld.c);
    -- CB2_LoadMap doesn't, so do it here. A generated floor then moves the
    -- player onto its generated warp tile.
    if warp_id >= 0 then
        x, y = rom_warp_tile(map, warp_id)
    end
    emu:write16(sb1 + SB1_POS + 0, (x or 0) & 0xFFFF)
    emu:write16(sb1 + SB1_POS + 2, (y or 0) & 0xFFFF)
    for _, a in ipairs({ dest, sb1 + SB1_LOCATION }) do
        emu:write8(a + 0, map.group)
        emu:write8(a + 1, map.num)
        emu:write8(a + 2, warp_id & 0xFF)
        emu:write16(a + 4, (x or 0) & 0xFFFF)
        emu:write16(a + 6, (y or 0) & 0xFFFF)
    end
    if rng ~= nil then
        mm.set_rng(rng)
        pending_rng = rng
    end
    emu:write32(sym.addr("gMain") + 4, sym.addr("CB2_LoadMap") | 1)
end

local function wait_for_overworld(map)
    local frames = 0
    repeat
        fw.yield()
        frames = frames + 1
    until mm.in_overworld() or frames > 600
    if not mm.in_overworld() then
        error(string.format("map %d.%d did not finish loading", map.group, map.num))
    end
    return frames
end

function mm.enter_floor(floor, rng)
    start_warp(floor, floor.arrival_warp, rng)
    local frames = wait_for_overworld(floor)
    return mm.snapshot(), frames
end

-- Put the player on tile (x, y) of `map` (any map, e.g. mm.ROUTE4) through
-- the same map load a warp uses, and wait until they have control.
function mm.warp_to_tile(map, x, y)
    start_warp(map, -1, nil, x, y)
    wait_for_overworld(map)
    return fw.wait_until(mm.player_has_control, 600,
        string.format("control after warping to %d.%d (%d,%d)", map.group, map.num, x, y))
end

-- Load time (P9): enter `map` through its warp `warp_id`, with the game's
-- random state set to `rng`, and count frames from handing the game the warp
-- (the moment a real warp's fade to black ends) until the player can move
-- again on the new map (map loaded, fade-in finished, controls unlocked).
-- Returns the frame count, or nil if control never came back in 900 frames.
function mm.timed_entry(map, warp_id, rng)
    start_warp(map, warp_id, rng)
    for frames = 1, 900 do
        fw.yield()
        local group, num = mm.current_map()
        if mm.in_overworld() and group == map.group and num == map.num
            and mm.player_has_control() then
            return frames
        end
    end
    return nil
end

-------------------------------------------------------------------------------
-- Choosing a random state that rolls a given seed
-------------------------------------------------------------------------------
--
-- The seed is the top 16 bits of gRngValue after some number k of Random()
-- calls, counted from the moment the test wrote gRngValue. (Random() runs
-- once per frame in the VBlank interrupt, plus whatever else the map load
-- does.) Random() is a linear congruential generator:
--     state_{n+1} = (A * state_n + C) mod 2^32
-- so after k calls, state_k = A^k * state_0 + (constant). Starting from
-- state_0 + delta instead gives state_k + A^k * delta. Choosing
-- delta = A^-k (the multiplicative inverse of A^k mod 2^32; it exists
-- because A is odd) makes state_k exactly one larger: the same top 16 bits,
-- so the same seed, but every Random() value AFTER the seed roll is
-- different. If the generator secretly used Random() after rolling the seed,
-- the two caves would differ.

local LCG_A = 1103515245
local LCG_C = 24691
local MASK32 = 0xFFFFFFFF

local function lcg(state)
    return (LCG_A * state + LCG_C) & MASK32
end

local function mul32(a, b)
    return (a * b) & MASK32  -- Lua integers wrap mod 2^64, so mod 2^32 is exact
end

local function inverse32(a)
    -- Newton's iteration for 1/a mod 2^32: each step doubles the correct bits.
    local x = a
    for _ = 1, 5 do
        x = mul32(x, (2 - mul32(a, x)) & MASK32)
    end
    return x
end

-- How many Random() calls it took to get from `rng` to the roll of `seed`
-- (the k above), or nil if not found within 4096 calls.
function mm.rng_steps(rng, seed)
    local state = rng & MASK32
    for k = 1, 4096 do
        state = lcg(state)
        if (state >> 16) == seed then return k, state end
    end
    return nil
end

-- Returns a gRngValue different from `rng` that rolls the same `seed`, or nil
-- if the seed can't be traced back to `rng` within 4096 Random() calls.
function mm.rng_with_same_seed(rng, seed)
    local k, state = mm.rng_steps(rng, seed)
    if k == nil then return nil end
    -- Bump state_k by +1, or by -1 if +1 would carry into the top 16 bits.
    local bump = ((state & 0xFFFF) == 0xFFFF) and MASK32 or 1
    local a_pow_k = 1
    for _ = 1, k do a_pow_k = mul32(a_pow_k, LCG_A) end
    return (rng + mul32(inverse32(a_pow_k), bump)) & MASK32
end

-- A gRngValue that rolls `seed` when the seed is the k-th Random() call
-- after the write (measure k with rng_steps on an identical entry). Runs the
-- generator backwards: state_{n-1} = (state_n - C) * A^-1 mod 2^32.
function mm.rng_for_seed(k, seed)
    local inv_a = inverse32(LCG_A)
    local state = ((seed & 0xFFFF) << 16) | 0x1234
    for _ = 1, k do
        state = mul32((state - LCG_C) & MASK32, inv_a)
    end
    return state
end

-------------------------------------------------------------------------------
-- Waiting for the player to have control
-------------------------------------------------------------------------------

-- True when no script is running and the player can move. The two statics
-- live in src/script.c.
function mm.player_has_control()
    return emu:read8(sym.addr("sGlobalScriptContextStatus")) == 2  -- CONTEXT_SHUTDOWN
        and emu:read8(sym.addr("sLockFieldControls")) == 0
end

-------------------------------------------------------------------------------
-- Saving and continuing
-------------------------------------------------------------------------------

local STARTMENU_SAVE = 4  -- enum in src/start_menu.c

-- struct Task (include/task.h), 0x28 bytes: TaskFunc func at 0x00, bool8
-- isActive at 0x04, s16 data[16] at 0x08. gTasks has 16. Menus keep their
-- state in data[], so tests read mm.TASK_DATA + 2 * i for data[i].
local TASK_SIZE, NUM_TASKS = 0x28, 16
mm.TASK_DATA = 0x08

-- The address of an active task running function `name`, or nil. Menus
-- are tasks, so this says which menu is waiting for input. A stored
-- function pointer has bit 0 set (the Thumb-mode flag, see symbols.lua),
-- which `& ~1` clears before comparing it with the symbol's address.
function mm.task_running(name)
    local tasks = sym.addr("gTasks")
    local func = sym.addr(name)
    for i = 0, NUM_TASKS - 1 do
        local t = tasks + i * TASK_SIZE
        if emu:read8(t + 4) ~= 0 and (emu:read32(t) & ~1) == func then return t end
    end
    return nil
end

-- Press START on the field and wait until the START menu takes input: its
-- task Task_StartMenuHandleInput has reached its second step (data[0] = 1)
-- with StartCB_HandleInput as the callback. (sStartMenuCallback alone isn't
-- enough: it keeps StartCB_HandleInput from the last time the menu was
-- open, and a key pressed the frame before that step is lost.)
--
-- The START press itself is lost now and then: the game reads the buttons
-- once per pass of its main loop, and a pass that runs long can miss a
-- press that lasts a single frame. The field locks its controls
-- (sLockFieldControls) on the frame it opens the menu, so while they stay
-- unlocked START is pressed again, up to 3 times. Returns true once the
-- menu takes input, within `timeout` frames (default 120) of the press it
-- saw.
function mm.open_start_menu(timeout)
    local lock = sym.addr("sLockFieldControls")
    local seen = false
    for _ = 1, 3 do
        fw.press("START")
        for _ = 1, 20 do
            if emu:read8(lock) ~= 0 then seen = true break end
            fw.yield()
        end
        if seen then break end
        fw.log("[START] the press was lost (the field controls are still unlocked): pressing again")
    end
    if not seen then return false end
    return fw.wait_until(function()
        local t = mm.task_running("Task_StartMenuHandleInput")
        return t ~= nil and emu:read16(t + mm.TASK_DATA) == 1
            and sym.is_func(emu:read32(sym.addr("sStartMenuCallback")), "StartCB_HandleInput")
    end, timeout or 120, "START menu open")
end

-- Save through START > SAVE > YES (and YES again to overwrite an older save).
-- Returns true once the game reports the save finished and the menu closed.
function mm.save_game()
    if not fw.wait_until(mm.player_has_control, 600, "player has control before saving") then
        return false
    end
    local counter_before = emu:read32(sym.addr("gSaveCounter"))

    if not mm.open_start_menu() then
        fw.log_error("the START menu never opened")
        return false
    end

    -- Find SAVE in the menu and move the cursor onto it. The list remembers
    -- its cursor between openings, so start from wherever it is now.
    local count = emu:read8(sym.addr("sNumStartMenuItems"))
    local order = sym.addr("sStartMenuOrder")
    local target = nil
    for i = 0, count - 1 do
        if emu:read8(order + i) == STARTMENU_SAVE then target = i end
    end
    if target == nil then
        fw.log_error("SAVE is not in the start menu")
        return false
    end
    local current = emu:read16(sym.addr("sListCursorPos"))
        + emu:read16(sym.addr("sListScrollOffset"))
    local key_name = target > current and "DOWN" or "UP"
    for _ = 1, math.abs(target - current) do
        fw.press(key_name)
        fw.wait_frames(6)
    end
    fw.press("A")

    -- Answer YES to "Would you like to save the game?" and, if a save
    -- already exists, to "...Is it okay to overwrite it?". Both menus open
    -- with the cursor on YES.
    local dialog = sym.addr("sSaveDialogCB")
    local yes_no = {
        sym.addr("SaveDialogCB_AskSaveHandleInput"),
        sym.addr("SaveDialogCB_AskOverwriteOrReplacePreviousFileHandleInput"),
    }
    local saved = false
    for _ = 1, 1200 do
        local cb = emu:read32(dialog) & ~1
        if cb == yes_no[1] or cb == yes_no[2] then
            fw.press("A")
            fw.wait_frames(10)
        end
        if emu:read32(sym.addr("gSaveCounter")) ~= counter_before then
            saved = true
            break
        end
        fw.yield()
    end
    if not saved then
        fw.log_error("the save never finished")
        return false
    end
    -- "<PLAYER> saved the game." closes by itself after a moment.
    return fw.wait_until(mm.player_has_control, 600, "save message closed")
end

-- Soft-reset the console and pick CONTINUE on the main menu. Skips the
-- "Previously on your quest" replay with B if one starts.
--
-- Returns a snapshot taken on the very first frame the overworld runs, before
-- any NPC has had a chance to take a step (so positions can be compared with
-- the save exactly), or nil on failure. Returns only after the player has
-- control again. `on_frame` (optional) is called on every frame from that
-- first one until the player has control, with the frames since the first
-- (0 on it), for a test that checks what the field shows by then.
function mm.continue_game(on_frame)
    emu:reset()
    -- Intro and title screen: A skips ahead until the main menu is up.
    local ok = false
    for _ = 1, 60 do
        fw.wait_frames(30)
        if sym.is_func(callback2(), "CB2_MainMenu") then ok = true break end
        fw.press("A")
    end
    if not ok then
        fw.log_error("never reached the main menu")
        return false
    end
    fw.wait_frames(60)
    fw.press("A")  -- CONTINUE is the first item and is selected by default

    -- The replay also runs in the overworld, so "in the overworld" only
    -- counts once gQuestLogState says no replay is playing.
    local quest_log_state = sym.addr("gQuestLogState")
    local first, first_at = nil, nil
    for i = 1, 2400 do
        local state = emu:read8(quest_log_state)
        if state >= 2 then  -- QL_STATE_PLAYBACK / QL_STATE_PLAYBACK_LAST
            fw.press("B")   -- B ends the replay
            fw.wait_frames(20)
        elseif mm.in_overworld() and mm.player_tile() ~= nil then
            if first == nil then first, first_at = mm.snapshot(), i end
            if on_frame then on_frame(i - first_at) end
            if mm.player_has_control() then return first end
        end
        fw.yield()
    end
    fw.log_error("Continue never reached the overworld with control")
    return nil
end

-- Save, then Continue. Returns two snapshots: `saved`, with the player and
-- objects as written to the save, and `loaded`, from the first overworld
-- frame after Continue. Returns nil (after logging why) if either step fails.
function mm.save_and_continue()
    if not mm.save_game() then return nil end
    local saved = mm.snapshot(true)
    local loaded = mm.continue_game()
    if loaded == nil then return nil end
    return saved, loaded
end

-------------------------------------------------------------------------------
-- Property checks
-------------------------------------------------------------------------------
--
-- Each property check is its own file in test/tests/mt_moon_checks/, so tickets
-- can add checks without editing a shared list. A check file returns:
--
--   {
--       id = "P8",
--       title = "determinism",
--       floors = { B1F = true },  -- optional: only run on these floors
--       run = function(h, floor, rng, snap)
--           -- h is this library, floor an entry of mm.FLOORS, rng the
--           -- gRngValue the floor was entered with, snap mm.snapshot().
--           return true                        -- pass
--           return false, "what went wrong"    -- fail
--       end,
--       summary = function(floor)  -- optional: a line for the log after
--           return "..."           -- the floor's seeds (e.g. P9's timings)
--       end,
--   }
--
-- A check may re-enter the floor (P8 and P9 do); its last entry must be a
-- plain mm.enter_floor() of the same floor, so the next check or seed
-- leaves the same map in the same just-loaded state (that state affects how
-- many Random() calls run before the next seed is rolled). It must judge
-- `snap`, which was taken before any check ran, so the order checks run in
-- doesn't matter.

function mm.load_checks(dir)
    local checks = {}
    local pipe = io.popen("ls '" .. dir .. "'/*.lua 2>/dev/null")
    if pipe == nil then return checks end
    for path in pipe:lines() do
        local check = dofile(path)
        check.file = path:match("([^/]+)$")
        checks[#checks + 1] = check
    end
    pipe:close()
    table.sort(checks, function(a, b) return a.file < b.file end)
    return checks
end

return mm
